/** Approved supplied flat PNGs. Private table/vector/name/URL mapping is never distributed. */
import {printedArtwork} from '../../modeling/artwork.js';
import {slab,materials,FACE} from './geometry.js';
const urls={pcb:new URL('./artwork/pcb.png',import.meta.url).href,top:new URL('./artwork/rear-top.png',import.meta.url).href,bottom:new URL('./artwork/rear-bottom.png',import.meta.url).href,left:new URL('./artwork/rear-left.png',import.meta.url).href,right:new URL('./artwork/rear-right.png',import.meta.url).href};
export function addStickers(host){const a=host.basicV27Assembly;const add=(key,target,size,position,face='back')=>{const panels=printedArtwork(host,{target,url:urls[key],size,position,face,depth:.12,name:'K001-V27 approved supplied '+key+' artwork'});if(panels)a.artworkPanels.push(...panels);};add('pcb',a.espFilm,[13.3,17.0],[-1.4,1.1,-3.67]);if(a.base){for(const[key,size,position]of[['top',[20.4,2.8],[0,24,-8.51]],['bottom',[20.4,2.8],[0,-24,-8.51]],['left',[2.8,38.1],[24,0,-8.51]],['right',[2.8,38.1],[-24,0,-8.51]]]){const film=slab(a.base,size[0],size[1],.025,.04,[position[0],position[1],-8.527],materials.plastic(0xe2e4dc,{roughness:.88}),[],.003);film.name='Actual rear '+key+' adhesive-film substrate';film.userData.role='physical-label-substrate';a.films[key]=film;add(key,film,size,[position[0],position[1],-8.529]);}}return a.artworkPanels;}
